    var search by rememberSaveable { mutableStateOf("") }
    val sourcePicker = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            result.data?.data?.let { model.selectFolder(it, result.data?.flags ?: 0, source = true) }
        }
    }
    val destinationPicker = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            result.data?.data?.let { model.selectFolder(it, result.data?.flags ?: 0, source = false) }
        }
    }
    fun choose(source: Boolean) {
        val intent = Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).apply {
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION or
                Intent.FLAG_GRANT_PREFIX_URI_PERMISSION)
            if (!source) addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
        }
        try {
            if (source) sourcePicker.launch(intent) else destinationPicker.launch(intent)
        } catch (_: ActivityNotFoundException) {
            model.reportPickerUnavailable()
        } catch (_: SecurityException) {
            model.reportPickerUnavailable()
        }
    }
    val filtered = state.files.filter { it.name.contains(search, ignoreCase = true) }
    Scaffold(containerColor = MaterialTheme.colorScheme.background) { padding ->
        LazyColumn(
            modifier = Modifier.fillMaxSize().padding(padding).padding(horizontal = 20.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
            item {
                Column(Modifier.padding(top = 20.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(stringResource(R.string.app_name), style = MaterialTheme.typography.headlineMedium)
                    Text(stringResource(R.string.manual_title), style = MaterialTheme.typography.titleLarge)
                    Text(stringResource(R.string.manual_intro))
                    Text(stringResource(R.string.version_label, BuildConfig.VERSION_NAME), style = MaterialTheme.typography.labelLarge)
                }
            }
            item {
                Panel {
                    Text(stringResource(R.string.source_title), style = MaterialTheme.typography.titleMedium)
                    Text(stringResource(R.string.source_hint))
                    FolderPath(state.folders.source)
                    Button(onClick = { choose(true) }, enabled = !state.busy, modifier = Modifier.fillMaxWidth()) {
                        Text(stringResource(R.string.choose_source))
                    }
                }
            }
            item {
                Panel {
                    Text(stringResource(R.string.destination_title), style = MaterialTheme.typography.titleMedium)
                    Text(stringResource(R.string.destination_hint))
                    FolderPath(state.folders.destination)
                    Button(onClick = { choose(false) }, enabled = !state.busy, modifier = Modifier.fillMaxWidth()) {
                        Text(stringResource(R.string.choose_destination))
                    }
                    OutlinedButton(
                        onClick = model::testFolders,
                        enabled = !state.busy && state.folders.source.isNotBlank() && state.folders.destination.isNotBlank(),
                        modifier = Modifier.fillMaxWidth(),
                    ) { Text(stringResource(R.string.test_folders)) }
                    Text(stringResource(if (state.tested) R.string.access_ready else R.string.access_not_tested))
                }
            }
            item {
                if (state.busy) {
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        val progress = state.progress
                        val label = when (progress?.phase) {
                            CopyPhase.WAITING -> R.string.waiting_for_file
                            CopyPhase.CHECKING -> R.string.checking_duplicate
                            CopyPhase.COPYING -> R.string.copy_working
                            CopyPhase.VERIFYING -> R.string.verifying_copy
                            null -> state.busyLabel
                        }
                        Text(stringResource(label))
                        if (progress?.phase == CopyPhase.COPYING && progress.total > 0) {
                            LinearProgressIndicator(
                                progress = { (progress.bytes.toFloat() / progress.total).coerceIn(0f, 1f) },
                                modifier = Modifier.fillMaxWidth(),
                            )
                        } else LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                    }
                }
                state.message?.let { message ->
                    Panel { Text(stringResource(message)) }
                }
            }
            if (state.operations.isNotEmpty()) {
                item { Text(stringResource(R.string.recent_operations), style = MaterialTheme.typography.titleMedium) }
                items(state.operations.take(3), key = { "operation-${it.id}" }) { operation ->
                    OperationCard(operation, !state.busy && state.tested, onRetry = { model.retry(operation) }) {
                        try {
                            context.startActivity(Intent(Intent.ACTION_VIEW).apply {
                                setDataAndType(Uri.parse(operation.destinationUri), CopyRules.mime(operation.outputName, ""))
                                addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                            })
                        } catch (_: ActivityNotFoundException) { model.reportOpenError() }
                        catch (_: SecurityException) { model.reportOpenError() }
                    }
                }
