                        modifier = Modifier.fillMaxWidth(),
                    ) { Text(stringResource(R.string.scan_files)) }
                    if (state.scanned) {
                        Text(stringResource(R.string.file_count, state.files.size))
                        OutlinedTextField(
                            value = search, onValueChange = { search = it },
                            label = { Text(stringResource(R.string.search_files)) },
                            singleLine = true, modifier = Modifier.fillMaxWidth(),
                        )
                        if (filtered.isEmpty()) Text(stringResource(R.string.no_files))
                    }
                }
            }
            items(filtered, key = { "file-${it.uri}" }) { file ->
                AudioCard(file, !state.busy && state.tested) { model.copy(file) }
            }
