@Composable
private fun AudioCard(file: AudioDocument, enabled: Boolean, onCopy: () -> Unit) {
    val context = LocalContext.current
    Panel {
        Literal(file.name)
        Text(if (file.size >= 0) Formatter.formatFileSize(context, file.size) else stringResource(R.string.size_unknown))
        if (file.modified > 0) Text(stringResource(R.string.modified_at, DateFormat.getDateTimeInstance().format(Date(file.modified))))
        Literal(file.documentId.substringBeforeLast('/', file.documentId.substringBefore(':') + ":"))
        Button(onClick = onCopy, enabled = enabled, modifier = Modifier.fillMaxWidth()) {
