    Panel {
        Literal(operation.sourceName)
        val status = when (operation.status) {
            "SUCCESS" -> R.string.status_success
            "SKIPPED" -> R.string.status_skipped
            "WAITING", "CHECKING" -> R.string.status_waiting
            "COPYING" -> R.string.status_copying
            else -> R.string.status_failed
        }
        Text(stringResource(status), style = MaterialTheme.typography.titleSmall)
        Text(DateFormat.getDateTimeInstance().format(Date(operation.startedAt)))
        if (operation.problem.isNotBlank()) {
            val problem = runCatching { Problem.valueOf(operation.problem) }.getOrDefault(Problem.UNKNOWN)
            Text(stringResource(problemString(problem)))
        }
        if (operation.status == "SUCCESS") {
            Literal(operation.outputName)
            FolderPath(operation.destinationTree)
            OutlinedButton(onClick = onOpen, modifier = Modifier.fillMaxWidth()) {
                Text(stringResource(R.string.open_copy))
            }
        } else if (operation.status == "FAILED" || operation.status == "WAITING") {
            OutlinedButton(onClick = onRetry, enabled = canRetry, modifier = Modifier.fillMaxWidth()) {
                Text(stringResource(R.string.retry_copy))
            }
        }
    }
