package com.audiocopier.app.ui

import android.app.Application
import android.content.Intent
import android.net.Uri
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.audiocopier.app.CopierApplication
import com.audiocopier.app.R
import com.audiocopier.app.copying.AudioDocument
import com.audiocopier.app.copying.CopyProblem
import com.audiocopier.app.copying.CopyProgress
import com.audiocopier.app.copying.Problem
import com.audiocopier.app.copying.problemOf
import com.audiocopier.app.data.FolderSettings
import com.audiocopier.app.data.Operation
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

data class CopierState(
    val folders: FolderSettings = FolderSettings(),
    val busy: Boolean = true,
    val busyLabel: Int = R.string.loading,
    val tested: Boolean = false,
    val scanned: Boolean = false,
    val files: List<AudioDocument> = emptyList(),
    val operations: List<Operation> = emptyList(),
    val progress: CopyProgress? = null,
    val message: Int? = null,
)

class CopierViewModel(application: Application) : AndroidViewModel(application) {
    private val app = application as CopierApplication
    private val repository = app.copies
    private val initialized = CompletableDeferred<Unit>()
    private val mutable = MutableStateFlow(CopierState())
    val state = mutable.asStateFlow()

    init {
        viewModelScope.launch {
            try {
                repository.recoverInterrupted()
                val folders = app.preferences.flow.first()
                mutable.update { it.copy(folders = folders) }
            } catch (error: Exception) {
                if (error is CancellationException) throw error
                mutable.update { it.copy(message = problemString(problemOf(error))) }
            } finally {
                mutable.update { it.copy(busy = false) }
                initialized.complete(Unit)
            }
        }
        viewModelScope.launch {
            try {
                repository.history.collect { operations ->
                    mutable.update { it.copy(operations = operations) }
                }
            } catch (error: Exception) {
                if (error is CancellationException) throw error
                mutable.update { it.copy(message = R.string.error_database) }
            }
        }
    }

    private fun action(label: Int, block: suspend () -> Unit) {
        if (mutable.value.busy) return
        mutable.update { it.copy(busy = true, busyLabel = label, message = null) }
        viewModelScope.launch {
            try {
                block()
            } catch (error: Exception) {
                if (error is CancellationException) throw error
                val problem = problemOf(error)
                mutable.update { it.copy(message = problemString(problem), tested = it.tested && problem != Problem.PERMISSION) }
            } finally {
                mutable.update { it.copy(busy = false, progress = null) }
            }
        }
    }

    fun reportPickerUnavailable() { mutable.update { it.copy(message = R.string.error_picker) } }
    fun reportOpenError() { mutable.update { it.copy(message = R.string.error_open) } }

    fun selectFolder(uri: Uri, flags: Int, source: Boolean) {
        if (!initialized.isCompleted) {
            viewModelScope.launch {
                initialized.await()
                selectFolder(uri, flags, source)
            }
            return
        }
        action(R.string.saving_folder) {
            val settings = mutable.value.folders
            repository.validateSelection(uri.toString(), if (source) settings.destination else settings.source)
            val needed = Intent.FLAG_GRANT_READ_URI_PERMISSION or
                (if (source) 0 else Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
            if (flags and needed != needed) throw CopyProblem(Problem.PERMISSION)
            withContext(Dispatchers.IO) {
                app.contentResolver.takePersistableUriPermission(uri, needed)
            }
            repository.validateReadable(uri.toString())
            app.preferences.save(source, uri.toString())
            val saved = app.preferences.flow.first()
            mutable.update {
                it.copy(
                    folders = saved, tested = false,
                    files = if (source) emptyList() else it.files,
                    scanned = if (source) false else it.scanned,
                    message = R.string.folder_saved,
                )
            }
        }
    }

    fun testFolders() = action(R.string.testing_folders) {
        mutable.update { it.copy(tested = false) }
        repository.testFolders(mutable.value.folders)
        mutable.update { it.copy(tested = true, message = R.string.test_passed) }
    }

    fun scan() = action(R.string.scanning) {
        mutable.update { it.copy(files = emptyList(), scanned = false) }
        val files = repository.scan(mutable.value.folders.source)
        mutable.update { it.copy(files = files, scanned = true) }
    }

    fun copy(file: AudioDocument) = action(R.string.copy_working) {
        if (!mutable.value.tested) throw CopyProblem(Problem.FOLDER_REQUIRED)
        val operation = repository.copy(mutable.value.folders, file) { progress ->
            mutable.update { it.copy(progress = progress) }
        }
        mutable.update {
            it.copy(tested = it.tested && operation.problem != "PERMISSION", message = when (operation.status) {
                "SUCCESS" -> R.string.copy_done
                "SKIPPED" -> R.string.error_duplicate
                else -> problemString(runCatching { Problem.valueOf(operation.problem) }.getOrDefault(Problem.UNKNOWN))
            })
        }
    }

    fun retry(operation: Operation) = copy(AudioDocument(
        uri = operation.sourceUri, name = operation.sourceName, mime = "",
        size = operation.sourceSize, modified = operation.sourceModified, documentId = "",
    ))
}

fun problemString(problem: Problem): Int = when (problem) {
    Problem.PERMISSION -> R.string.error_permission
    Problem.MISSING -> R.string.error_missing
    Problem.IO -> R.string.error_io
    Problem.SPACE -> R.string.error_space
    Problem.LOCAL_ONLY -> R.string.error_local_only
    Problem.OVERLAP -> R.string.error_overlap
    Problem.NOT_READY -> R.string.error_not_ready
    Problem.SOURCE_CHANGED -> R.string.error_source_changed
    Problem.VERIFY -> R.string.error_verify
    Problem.FOLDER_REQUIRED -> R.string.error_folders
    Problem.TOO_MANY -> R.string.error_many
    Problem.INTERRUPTED -> R.string.error_interrupted
    Problem.CLEANUP -> R.string.error_cleanup
    Problem.DATABASE -> R.string.error_database
    Problem.DUPLICATE -> R.string.error_duplicate
    Problem.UNKNOWN -> R.string.error_unknown
}

